package com.alpharip.staffmod.AuditFindingsBoard;
import java.util.*; 
public final class AuditFindingsService {
 private final AuditFindingsRegistry registry;public AuditFindingsService(AuditFindingsRegistry r){if(r==null)throw new IllegalArgumentException("Registry required");registry=r;}
 public AuditFinding create(String t,String d,AuditFindingCategory c,AuditFindingSeverity s,String owner,long due,long now){AuditFindingsValidator.validate(t,d,c,s);AuditFinding f=new AuditFinding(UUID.randomUUID().toString(),t,d,c,s,owner,due,now);registry.add(f);return f;}
 public void update(String id,String t,String d,AuditFindingCategory c,AuditFindingSeverity s,String owner,long due,long now){AuditFindingsValidator.validate(t,d,c,s);require(id).revise(t,d,c,s,owner,due,now);}
 public void setStatus(String id,AuditFindingStatus s,String actor,long now){require(id).setStatus(s,actor,now);}public void assign(String id,String a,String actor,long now){require(id).assign(a,actor,now);}
 public void addNote(String id,String author,String text,long now){require(id).addNote(author,text,now);}public void addAction(String id,String text,String assignee,long now){require(id).addAction(text,assignee,now);}
 public void completeAction(String id,String actionId,boolean complete,long now){require(id).completeAction(actionId,complete,now);}public void addEvidence(String id,String label,String ref,String actor,long now){require(id).addEvidence(label,ref,actor,now);}
 public void resolve(String id,String outcome,String rationale,String actor,long now){require(id).resolve(outcome,rationale,actor,now);}public boolean remove(String id){return registry.remove(id);}
 public List<AuditFinding> find(AuditFindingsFilter filter,final AuditFindingsSort sort){List<AuditFinding> out=new ArrayList<AuditFinding>();for(AuditFinding f:registry.getAll())if(filter==null||filter.matches(f))out.add(f);Collections.sort(out,new Comparator<AuditFinding>(){public int compare(AuditFinding a,AuditFinding b){AuditFindingsSort s=sort==null?AuditFindingsSort.NEWEST:sort;switch(s){case OLDEST:return Long.compare(a.getCreatedAt(),b.getCreatedAt());case SEVERITY_DESCENDING:return Integer.compare(b.getSeverity().getWeight(),a.getSeverity().getWeight());case DUE_DATE_ASCENDING:return Long.compare(a.getDueAt()==0?Long.MAX_VALUE:a.getDueAt(),b.getDueAt()==0?Long.MAX_VALUE:b.getDueAt());case RECENTLY_UPDATED:return Long.compare(b.getUpdatedAt(),a.getUpdatedAt());default:return Long.compare(b.getCreatedAt(),a.getCreatedAt());}}});return out;}
 public AuditFindingsSummary summarize(long now){int o=0,r=0,a=0,rs=0,c=0,cr=0,d=0,u=0;for(AuditFinding f:registry.getAll()){switch(f.getStatus()){case OPEN:o++;break;case IN_REVIEW:r++;break;case ACTION_REQUIRED:a++;break;case RESOLVED:rs++;break;case CLOSED:c++;break;}if(f.getSeverity()==AuditFindingSeverity.CRITICAL&&f.getStatus()!=AuditFindingStatus.CLOSED)cr++;if(f.getDueAt()>0&&f.getDueAt()<now&&f.getStatus()!=AuditFindingStatus.RESOLVED&&f.getStatus()!=AuditFindingStatus.CLOSED)d++;for(AuditFindingAction x:f.getActions())if(!x.isCompleted())u++;}return new AuditFindingsSummary(registry.size(),o,r,a,rs,c,cr,d,u);}
 private AuditFinding require(String id){AuditFinding f=registry.get(id);if(f==null)throw new IllegalArgumentException("Finding not found: "+id);return f;}
}
